/**
 * Crea el tema canónico tema-137: "La instrucción operativa de trabajo:
 * concepto y aplicación" y lo asigna como Tema 19 (bloque-2, numero=21)
 * de la oposición Oficial Cementerio (Ayto. Zaragoza).
 *
 * Corresponde al TEMA 19 oficial del Anexo I (bases2110.pdf): "la
 * Instrucción operativa de trabajo. Concepto, aplicación."
 *
 * Fuente primaria verificada mediante búsqueda en esta sesión de
 * trabajo: NTP 560 ("Sistema de gestión preventiva: procedimiento de
 * elaboración de las instrucciones de trabajo"), Nota Técnica de
 * Prevención del Instituto Nacional de Seguridad y Salud en el Trabajo
 * (INSST), que constituye la referencia técnica de uso habitual en
 * España para el concepto de instrucción de trabajo dentro de un
 * sistema de gestión preventiva, sin atribuirle apartados concretos no
 * releídos directamente. Se cita también, como referencia complementaria
 * ya empleada en otros temas del proyecto, la Ley 31/1995 como marco
 * general en el que se inserta cualquier documento de gestión preventiva
 * (evaluación de riesgos, planificación, procedimientos, instrucciones).
 *
 * Tres secciones:
 * 1. concepto-instruccion-operativa-trabajo
 * 2. elementos-estructura-instruccion-trabajo
 * 3. aplicacion-elaboracion-instrucciones-cementerio
 *
 * Uso: node --env-file=.env.local scripts/seed-tema-137-instruccion-operativa-trabajo.mjs
 */
const URL_BASE = process.env.NEXT_PUBLIC_SUPABASE_URL;
const SERVICE_KEY = process.env.SUPABASE_SERVICE_ROLE_KEY;

if (!URL_BASE || !SERVICE_KEY) {
  console.error("❌ Faltan NEXT_PUBLIC_SUPABASE_URL o SUPABASE_SERVICE_ROLE_KEY.");
  process.exit(1);
}

const HEADERS = { apikey: SERVICE_KEY, Authorization: `Bearer ${SERVICE_KEY}`, "Content-Type": "application/json" };
