const S1 = "concepto-instruccion-operativa-trabajo";
console.log(`📝 flashcards (${S1})...`);
await insertar("flashcards", [
  { anverso: "¿Qué es una instrucción operativa de trabajo, dentro de un sistema de gestión preventiva?", reverso: "Un documento que establece pautas o directrices concretas y detalladas para la realización de una tarea determinada, fijando objetivos, ámbito, definiciones, agentes implicados y desarrollo, con el fin de promover actitudes y procedimientos seguros que eviten accidentes" },
  { anverso: "¿Qué relación jerárquica suele existir entre un procedimiento de prevención y una instrucción de trabajo dentro de un mismo sistema de gestión preventiva?", reverso: "El procedimiento fija el marco general de una actividad o proceso (por ejemplo, cómo se gestiona la evaluación de riesgos de la empresa), mientras que la instrucción de trabajo desarrolla en detalle cómo realizar una tarea concreta dentro de ese marco, siendo un documento más específico y operativo" },
  { anverso: "¿Qué es la NTP 560 del Instituto Nacional de Seguridad y Salud en el Trabajo (INSST)?", reverso: "La Nota Técnica de Prevención que desarrolla el procedimiento de elaboración de las instrucciones de trabajo dentro de un sistema de gestión preventiva, constituyendo la referencia técnica de uso habitual en España sobre este concepto" },
  { anverso: "¿Por qué una instrucción de trabajo se considera un documento operativo, frente a otros documentos más generales del sistema de PRL (como la política preventiva de la empresa)?", reverso: "Porque su contenido se centra en el 'cómo hacer' una tarea concreta paso a paso, con un nivel de detalle práctico y aplicable directamente por quien la ejecuta, a diferencia de documentos más generales que fijan principios o compromisos de carácter amplio" },
  { anverso: "¿Qué finalidad última persigue la elaboración de una instrucción operativa de trabajo, según su propia definición?", reverso: "Promover actitudes y procedimientos seguros en la realización de una tarea concreta, con el objetivo final de evitar accidentes derivados de una ejecución inadecuada o de un desconocimiento de los riesgos y las medidas preventivas aplicables a esa tarea" },
  { anverso: "¿Por qué no toda tarea de una organización requiere necesariamente una instrucción de trabajo específica, sino solo aquellas que lo justifiquen?", reverso: "Porque elaborar instrucciones para cualquier tarea, por sencilla o de bajo riesgo que sea, generaría una carga documental excesiva y poco útil; las instrucciones suelen reservarse para tareas con un riesgo relevante, una complejidad significativa, o donde la variabilidad de ejecución entre distintas personas pueda comprometer la seguridad" },
  { anverso: "¿Qué relación existe entre una instrucción operativa de trabajo y la evaluación de riesgos de un puesto, ya vista en el tema de PRL de esta oposición?", reverso: "La instrucción de trabajo debería derivarse de los riesgos identificados en la evaluación de riesgos correspondiente a esa tarea, desarrollando en detalle las medidas preventivas concretas que la propia evaluación haya determinado como necesarias para controlar esos riesgos" },
  { anverso: "¿Por qué puede considerarse que un procedimiento interno del tipo PPRL-1605 (visto en el tema anterior de esta oposición) es, en esencia, un ejemplo de instrucción o procedimiento operativo de trabajo aplicado a una tarea concreta?", reverso: "Porque, según su propio nombre y estructura documental, se trata de un documento que desarrollaría en detalle cómo realizar de forma segura una tarea específica (el enterramiento en distintos tipos de unidad), coincidiendo en su naturaleza con el concepto general de instrucción operativa de trabajo estudiado en este tema" },
  { anverso: "¿Por qué resulta más útil para el trabajador disponer de una instrucción de trabajo específica que confiar exclusivamente en la formación general recibida al inicio de su relación laboral?", reverso: "Porque una instrucción de trabajo permite consultar en cualquier momento, de forma concreta y actualizada, los pasos y las precauciones exactas de una tarea determinada, complementando la formación general (que puede no cubrir con el mismo detalle cada tarea específica ni mantenerse igual de presente con el paso del tiempo)" },
  { anverso: "¿Por qué es relevante que el oficial de cementerio comprenda el concepto general de instrucción operativa de trabajo, más allá de disponer o no del contenido concreto de una instrucción determinada como el PPRL-1605?", reverso: "Porque comprender qué es y para qué sirve este tipo de documento permite valorar con criterio su utilidad, colaborar en su elaboración o revisión si se le solicita, y entender por qué la Administración puede mantener documentos de este tipo como parte de su sistema interno de gestión preventiva" },
].map((f) => ({ ...f, tema_slug: TEMA, seccion: S1 })));

