const S2 = "elementos-estructura-instruccion-trabajo";
console.log(`📝 flashcards (${S2})...`);
await insertar("flashcards", [
  { anverso: "¿Qué son los objetivos de una instrucción operativa de trabajo, como uno de sus elementos habituales de estructura?", reverso: "La finalidad concreta que persigue el documento, expresando de forma clara qué se pretende conseguir (por ejemplo, realizar una tarea determinada sin riesgo de accidente), y que sirve de referencia para valorar si la instrucción cumple realmente su propósito" },
  { anverso: "¿Qué es el ámbito de aplicación de una instrucción de trabajo, y por qué debe delimitarse con claridad?", reverso: "El conjunto de situaciones, tareas o puestos concretos a los que resulta aplicable la instrucción; debe delimitarse con claridad para evitar tanto lagunas (tareas sin cobertura) como confusiones sobre cuándo debe seguirse ese documento en concreto" },
  { anverso: "¿Qué son las definiciones incluidas en una instrucción de trabajo, y qué función cumplen dentro del documento?", reverso: "Las explicaciones de los términos técnicos o específicos empleados en la instrucción, que garantizan que cualquier persona que la consulte comprenda el significado exacto de cada concepto, evitando interpretaciones distintas entre distintos usuarios del documento" },
  { anverso: "¿Qué son los agentes implicados en una instrucción de trabajo, y por qué es relevante identificarlos con claridad?", reverso: "Las personas o los perfiles profesionales que intervienen en la ejecución de la tarea regulada (por ejemplo, el propio trabajador, un supervisor, un servicio de prevención), cuya identificación clara evita confusiones sobre quién debe hacer qué en cada momento del proceso" },
  { anverso: "¿Qué son los documentos de referencia (o documentos relacionados) citados dentro de una instrucción de trabajo?", reverso: "Otras normas, procedimientos o registros con los que la instrucción guarda relación (por ejemplo, la evaluación de riesgos del puesto, una norma legal aplicable, un registro de formación), que sitúan el documento dentro del conjunto más amplio del sistema de gestión preventiva" },
  { anverso: "¿Qué es el desarrollo (o cuerpo principal) de una instrucción de trabajo, como su elemento central?", reverso: "La descripción paso a paso de cómo debe realizarse la tarea de forma segura, incluyendo las precauciones, los medios necesarios y el orden de las operaciones, siendo la parte más extensa y directamente aplicable del documento" },
  { anverso: "¿Por qué el orden y la claridad en la redacción del desarrollo de una instrucción de trabajo resultan tan importantes como el contenido técnico en sí mismo?", reverso: "Porque una instrucción confusa o mal ordenada, aunque contenga la información técnica correcta, puede dar lugar a interpretaciones erróneas o a la omisión involuntaria de algún paso relevante por parte de quien la consulta durante la ejecución real de la tarea" },
  { anverso: "¿Por qué debe revisarse y actualizarse periódicamente una instrucción de trabajo, en lugar de considerarla un documento definitivo una vez elaborado?", reverso: "Porque las condiciones de la tarea pueden cambiar con el tiempo (nuevos equipos, cambios normativos, lecciones aprendidas de incidentes), y una instrucción no actualizada puede quedar desfasada respecto a la forma más segura y eficaz de realizar la tarea en cada momento" },
  { anverso: "¿Qué diferencia existe entre elaborar una instrucción de trabajo desde un despacho, sin conocimiento directo de la tarea, y elaborarla con la participación de quienes la realizan habitualmente?", reverso: "La participación de quienes realizan la tarea habitualmente aporta un conocimiento práctico y detallado de las condiciones reales de ejecución que difícilmente puede reproducirse desde fuera, mejorando tanto la precisión técnica como la aceptación posterior del documento por parte de sus destinatarios" },
  { anverso: "¿Por qué es relevante que el oficial de cementerio conozca la estructura habitual de una instrucción de trabajo (objetivos, ámbito, definiciones, agentes, documentos de referencia, desarrollo), más allá del contenido concreto de una instrucción determinada?", reverso: "Porque conocer esa estructura permite interpretar y aplicar correctamente cualquier instrucción de trabajo que se le presente, e incluso colaborar en su elaboración o mejora si se le solicita, aportando su experiencia práctica sobre las tareas concretas del oficio" },
].map((f) => ({ ...f, tema_slug: TEMA, seccion: S2 })));

